<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';
$accountantId = accountant_require_login();
$err = '';
$ok = '';

if (!empty($_GET['registered'])) $ok = 'Cadastro concluído. Agora informe o CNPJ das empresas que você atende para solicitar acesso.';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  try {
    accountant_check_csrf((string)($_POST['csrf'] ?? ''));
    $action = (string)($_POST['action'] ?? '');
    if ($action === 'password') {
      $current = (string)($_POST['current_password'] ?? '');
      $new = (string)($_POST['new_password'] ?? '');
      $confirm = (string)($_POST['confirm_password'] ?? '');
      if (strlen($new) < 8) throw new RuntimeException('A nova senha deve possuir pelo menos 8 caracteres.');
      if ($new !== $confirm) throw new RuntimeException('A confirmação da nova senha não confere.');
      $st = $pdo->prepare('SELECT password_hash FROM accountants WHERE id=? AND is_active=1');
      $st->execute([$accountantId]);
      $hash = (string)($st->fetchColumn() ?: '');
      if ($hash === '' || !password_verify($current, $hash)) throw new RuntimeException('A senha atual está incorreta.');
      $pdo->prepare('UPDATE accountants SET password_hash=?,updated_at=NOW() WHERE id=?')
        ->execute([password_hash($new, PASSWORD_DEFAULT), $accountantId]);
      $ok = 'Senha alterada com sucesso.';
    } elseif ($action === 'request_access') {
      $companyRequested = accounting_request_access(
        $pdo,
        $accountantId,
        (string)($_POST['company_cnpj'] ?? ''),
        (string)($_POST['request_message'] ?? '')
      );
      $ok = 'Solicitação enviada para ' . (string)($companyRequested['display_name'] ?? $companyRequested['name'] ?? 'a empresa') . '. Aguarde a aprovação do administrador.';
    }
  } catch (Throwable $e) {
    $err = $e->getMessage();
  }
}

$companies = accounting_linked_companies($pdo, $accountantId);
$requests = [];
try { $requests = accounting_accountant_requests($pdo, $accountantId); } catch (Throwable $e) { $err = $err ?: $e->getMessage(); }
$pendingRequests = count(array_filter($requests, static fn(array $r): bool => strtoupper((string)($r['status'] ?? '')) === 'PENDENTE'));

$allowed = [];
foreach ($companies as $c) $allowed[(int)$c['id']] = $c;
$firstCompanyId = $allowed ? (int)array_key_first($allowed) : 0;
$selected = (int)($_GET['company'] ?? $_SESSION['accountant_company_id'] ?? $firstCompanyId);
if ($selected <= 0 || !isset($allowed[$selected])) $selected = $firstCompanyId;
if ($selected > 0) $_SESSION['accountant_company_id'] = $selected; else unset($_SESSION['accountant_company_id']);
$company = $selected > 0 ? ($allowed[$selected] ?? null) : null;

$defaultView = $companies ? 'closures' : 'requests';
$view = (string)($_GET['view'] ?? $defaultView);
if (!in_array($view, ['closures', 'documents', 'products', 'requests', 'settings'], true)) $view = $defaultView;
if (!$companies && in_array($view, ['closures', 'documents', 'products'], true)) $view = 'requests';

$closures = [];
$filesByClosure = [];
if ($selected > 0 && $view === 'closures') {
  try {
    $st = $pdo->prepare("SELECT * FROM accounting_closures WHERE company_id=? AND status='CONCLUIDO' ORDER BY period_end DESC,created_at DESC,id DESC LIMIT 80");
    $st->execute([$selected]);
    $closures = $st->fetchAll(PDO::FETCH_ASSOC) ?: [];
    $filesByClosure = accounting_files_by_closure($pdo, $selected, array_column($closures, 'id'));
  } catch (Throwable $e) {
    $err = $err ?: $e->getMessage();
  }
}

$ini = accounting_validate_date((string)($_GET['ini'] ?? date('Y-m-01')), date('Y-m-01'));
$fim = accounting_validate_date((string)($_GET['fim'] ?? date('Y-m-d')), date('Y-m-d'));
if ($ini > $fim) [$ini, $fim] = [$fim, $ini];
$model = trim((string)($_GET['model'] ?? ''));
if (!in_array($model, ['', '55', '65'], true)) $model = '';
$series = trim((string)($_GET['series'] ?? ''));
$accessKey = accounting_digits((string)($_GET['access_key'] ?? ''));
$number = trim((string)($_GET['number'] ?? ''));
if ($number !== '' && !preg_match('/^\d+$/', $number)) $number = '';
$status = strtoupper(trim((string)($_GET['status'] ?? '')));
$movement = strtoupper(trim((string)($_GET['movement'] ?? 'TODOS')));
$movementOptions = accounting_document_movement_options();
if (!isset($movementOptions[$movement])) $movement = 'TODOS';
$page = max(1, (int)($_GET['page'] ?? 1));
$perPage = 100;
$filters = ['ini'=>$ini,'fim'=>$fim,'model'=>$model,'series'=>$series,'access_key'=>$accessKey,'number'=>$number,'status'=>$status,'movement'=>$movement];
$documentResult = ['rows'=>[], 'total'=>0, 'page'=>1, 'per_page'=>$perPage, 'pages'=>1];
$documentTotals = ['documents_count'=>0,'total_document'=>0,'total_products'=>0,'total_icms'=>0,'total_pis'=>0,'total_cofins'=>0,'total_fcp_st'=>0,'total_cbs'=>0,'total_ibs_uf'=>0,'total_ibs_mun'=>0,'total_tributacao'=>0,'cfop'=>[],'icms'=>[],'pis'=>[],'cofins'=>[]];
$filterOptions = ['series'=>[], 'statuses'=>[]];
if ($view === 'documents' && $selected > 0) {
  try {
    $filterOptions = accounting_document_filter_options($pdo, $selected);
    $documentResult = accounting_search_documents($pdo, $selected, $filters, $page, $perPage);
    $documentTotals = accounting_document_totals($pdo, $selected, $filters);
  } catch (Throwable $e) {
    $err = $err ?: $e->getMessage();
  }
}
$docs = $documentResult['rows'];
$documentQueryBase = ['company'=>$selected,'view'=>'documents','ini'=>$ini,'fim'=>$fim,'model'=>$model,'series'=>$series,'access_key'=>$accessKey,'number'=>$number,'status'=>$status,'movement'=>$movement];
$documentUrl = static function(array $extra = []) use ($documentQueryBase): string { return '?' . http_build_query(array_merge($documentQueryBase, $extra)); };
$documentReportQuery = $documentQueryBase; unset($documentReportQuery['view']);
$documentPdfUrl = 'documentos_relatorio.php?' . http_build_query(array_merge($documentReportQuery,['format'=>'pdf']));
$documentPrintUrl = 'documentos_relatorio.php?' . http_build_query(array_merge($documentReportQuery,['format'=>'print']));
$documentXmlAllUrl = 'xml_download.php?' . http_build_query(array_merge($documentReportQuery,['mode'=>'all']));
$statusClass = static fn(string $value): string => strtolower(preg_replace('/[^A-Z0-9_-]+/i', '_', $value) ?: 'outro');

$productFilters = [
  'ini'=>$ini,
  'fim'=>$fim,
  'model'=>$model,
  'direction'=>strtoupper(trim((string)($_GET['direction'] ?? ''))),
  'q'=>trim((string)($_GET['product_q'] ?? '')),
  'ncm'=>preg_replace('/\D+/', '', (string)($_GET['ncm'] ?? '')) ?: '',
  'cest'=>preg_replace('/\D+/', '', (string)($_GET['cest'] ?? '')) ?: '',
  'cfop'=>preg_replace('/\D+/', '', (string)($_GET['cfop'] ?? '')) ?: '',
  'icms_cst'=>trim((string)($_GET['icms_cst'] ?? '')),
  'pis_cst'=>trim((string)($_GET['pis_cst'] ?? '')),
  'cofins_cst'=>trim((string)($_GET['cofins_cst'] ?? '')),
  'ibscbs_cst'=>trim((string)($_GET['ibscbs_cst'] ?? '')),
];
if (!in_array($productFilters['direction'], ['', 'ENTRADA', 'SAIDA'], true)) $productFilters['direction']='';
$productPage=max(1,(int)($_GET['product_page'] ?? 1));
$productResult=['rows'=>[],'total'=>0,'page'=>1,'per_page'=>150,'pages'=>1];
$productTotals=['items_count'=>0,'products_count'=>0,'quantity_total'=>0,'total_value'=>0,'total_icms'=>0,'total_pis'=>0,'total_cofins'=>0,'total_ibscbs'=>0];
$productOptions=['icms'=>[],'pis'=>[],'cofins'=>[],'ibscbs'=>[]];
if ($view==='products' && $selected>0) {
  try {
    $productOptions=accounting_product_filter_options($pdo,$selected);
    $productResult=accounting_search_product_items($pdo,$selected,$productFilters,$productPage,150);
    $productTotals=accounting_product_totals($pdo,$selected,$productFilters);
  } catch (Throwable $e) {
    $err=$err ?: $e->getMessage();
  }
}
$productRows=$productResult['rows'];
$productQueryBase=array_merge(['company'=>$selected,'view'=>'products'],[
  'ini'=>$ini,'fim'=>$fim,'model'=>$model,'direction'=>$productFilters['direction'],'product_q'=>$productFilters['q'],
  'ncm'=>$productFilters['ncm'],'cest'=>$productFilters['cest'],'cfop'=>$productFilters['cfop'],
  'icms_cst'=>$productFilters['icms_cst'],'pis_cst'=>$productFilters['pis_cst'],'cofins_cst'=>$productFilters['cofins_cst'],'ibscbs_cst'=>$productFilters['ibscbs_cst'],
]);
$productUrl=static function(array $extra=[]) use($productQueryBase): string { return '?' . http_build_query(array_merge($productQueryBase,$extra)); };
$productExportUrl='produtos_exportar.php?' . http_build_query($productQueryBase);
?>
<!doctype html>
<html lang="pt-br">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Central do Contador Próspero</title>
<style>
:root{--p:#0b1f5b;--s:#2454d6;--a:#00b8ff;--line:#dbe4f0;--muted:#64748b}*{box-sizing:border-box}body{margin:0;font-family:"Segoe UI",system-ui,Arial,sans-serif;background:#f4f7fb;color:#0f172a}.top{position:sticky;top:0;z-index:20;background:linear-gradient(135deg,var(--p),var(--s));color:#fff;padding:14px 22px;box-shadow:0 12px 34px rgba(11,31,91,.18)}.topin{max-width:1380px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:14px}.brand{display:flex;align-items:center;gap:11px}.brand img{width:45px;height:45px;object-fit:contain;background:#fff;border-radius:14px;padding:5px}.brand strong{display:block;font-size:18px}.brand span{font-size:12px;color:#dff6ff}.user{text-align:right}.user a{color:#fff;text-decoration:none;font-weight:800;margin-left:12px}.page{max-width:1380px;margin:0 auto;padding:22px}.hero{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:16px}.hero h1{margin:0;color:var(--p);font-size:30px;letter-spacing:-.04em}.hero p{margin:6px 0 0;color:var(--muted)}.company-select{min-width:290px}.company-select select{width:100%;height:46px;border:1px solid var(--line);border-radius:14px;padding:0 12px;background:#fff;font:inherit;font-weight:750}.msg{padding:12px 14px;border-radius:14px;margin-bottom:14px}.msg.err{background:#fef2f2;color:#b91c1c;border:1px solid #fecaca}.msg.ok{background:#ecfdf5;color:#047857;border:1px solid #a7f3d0}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.tabs a{padding:10px 13px;border-radius:12px;background:#fff;border:1px solid var(--line);color:#334155;text-decoration:none;font-weight:850}.tabs a.active{background:var(--p);color:#fff;border-color:var(--p)}.tabs .count{display:inline-flex;min-width:20px;height:20px;align-items:center;justify-content:center;margin-left:5px;border-radius:999px;background:#f59e0b;color:#fff;font-size:11px}.card{background:#fff;border:1px solid var(--line);border-radius:20px;padding:18px;box-shadow:0 10px 30px rgba(15,23,42,.04);margin-bottom:14px}.card h2{margin:0 0 12px;color:var(--p)}.card h3{margin:0;color:var(--p)}.kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-bottom:14px}.kpi{background:#fff;border:1px solid var(--line);border-radius:18px;padding:16px;min-width:0}.kpi span{display:block;color:var(--muted);font-size:12px;font-weight:800}.kpi strong{display:block;margin-top:5px;font-size:21px;color:var(--p);word-break:break-word}.closure{border-top:1px solid #e5eaf2;padding:16px 0}.closure:first-of-type{border-top:0}.closure-head{display:flex;justify-content:space-between;gap:16px}.closure h3{margin:0;color:#0f172a}.closure p{margin:5px 0 0;color:var(--muted)}.badge,.request-status{display:inline-flex;padding:6px 9px;border-radius:999px;background:#ecfdf5;color:#047857;border:1px solid #a7f3d0;font-size:11px;font-weight:900}.request-status.pendente{background:#fff7ed;color:#c2410c;border-color:#fed7aa}.request-status.negado{background:#fef2f2;color:#b91c1c;border-color:#fecaca}.request-status.aprovado{background:#ecfdf5;color:#047857;border-color:#a7f3d0}.status-badge{display:inline-flex;max-width:180px;padding:5px 8px;border-radius:999px;background:#f1f5f9;color:#475569;font-size:11px;font-weight:900;white-space:nowrap}.status-badge.autorizada,.status-badge.importada{background:#dcfce7;color:#15803d}.status-badge.cancelada,.status-badge.rejeitada,.status-badge.erro_autorizacao{background:#fee2e2;color:#b91c1c}.files{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px;margin-top:12px}.file{display:block;padding:11px 12px;border:1px solid var(--line);border-radius:14px;text-decoration:none;color:#0f172a}.file:hover{border-color:var(--s);background:#f8fbff}.file.primary{background:linear-gradient(135deg,var(--p),var(--s));color:#fff;border-color:transparent}.file strong,.file span{display:block}.file span{font-size:11px;opacity:.72;margin-top:3px;word-break:break-word}.filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;align-items:end}.filters label,.request-form label{display:block;font-size:12px;font-weight:850;margin-bottom:6px}.filters input,.filters select,.request-form input,.request-form textarea{width:100%;height:43px;border:1px solid var(--line);border-radius:12px;padding:0 10px;background:#fff;font:inherit}.request-form{display:grid;grid-template-columns:minmax(240px,.8fr) minmax(300px,1.2fr) auto;gap:10px;align-items:end}.request-form textarea{height:76px;padding:10px;resize:vertical}.filter-actions{display:flex;gap:8px;align-items:center}.btn{display:inline-flex;align-items:center;justify-content:center;height:43px;border:0;border-radius:12px;padding:0 14px;background:var(--s);color:#fff;font-weight:900;cursor:pointer;text-decoration:none;white-space:nowrap}.btn.secondary{background:#fff;color:#334155;border:1px solid var(--line)}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;min-width:1040px}.table.compact{min-width:580px}.table.requests{min-width:760px}.table th,.table td{padding:10px 9px;border-bottom:1px solid #e9eef5;text-align:left;font-size:13px;vertical-align:top}.table th{background:#f8fafc;color:#475569;position:sticky;top:0}.right{text-align:right!important}.key{display:block;max-width:270px;word-break:break-all;font-size:11px;color:#475569}.empty{padding:24px;text-align:center;color:var(--muted)}.settings{display:grid;grid-template-columns:1fr 1fr;gap:14px}.settings input{width:100%;height:43px;border:1px solid var(--line);border-radius:12px;padding:0 10px;margin-top:6px}.settings label{display:block;font-size:12px;font-weight:850;margin-top:8px}.settings .btn{margin-top:13px}.muted{color:var(--muted)}.note{margin-top:10px;padding:10px 12px;border-left:4px solid var(--a);background:#f8fafc;color:#475569;border-radius:0 12px 12px 0}.tax-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.group-card{background:#fff;border:1px solid var(--line);border-radius:20px;overflow:hidden;box-shadow:0 10px 30px rgba(15,23,42,.04)}.group-head{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:15px 17px;border-bottom:1px solid #e9eef5;background:#f8fafc}.group-head span{font-size:12px;color:var(--muted);font-weight:800}.group-empty{padding:20px;color:var(--muted);text-align:center}.results-head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:12px}.results-head h2{margin:0}.pagination{display:flex;gap:6px;align-items:center;justify-content:flex-end;flex-wrap:wrap;margin-top:14px}.pagination a,.pagination span{display:inline-flex;min-width:38px;height:38px;align-items:center;justify-content:center;border:1px solid var(--line);border-radius:11px;background:#fff;color:#334155;text-decoration:none;font-weight:850}.pagination span.active{background:var(--p);color:#fff;border-color:var(--p)}@media(max-width:1050px){.kpis{grid-template-columns:repeat(3,minmax(0,1fr))}.filters{grid-template-columns:repeat(2,minmax(0,1fr))}.request-form{grid-template-columns:1fr 1fr}.request-form .request-action{grid-column:1/-1}}@media(max-width:800px){.hero,.closure-head{display:block}.company-select{margin-top:12px}.kpis{grid-template-columns:1fr 1fr}.tax-grid{grid-template-columns:1fr}.settings{grid-template-columns:1fr}.topin{align-items:flex-start}.user span{display:none}}@media(max-width:520px){.page{padding:14px}.filters,.kpis,.request-form{grid-template-columns:1fr}.filter-actions{display:grid;grid-template-columns:1fr 1fr}.user a{display:block;margin:4px 0 0}.results-head{display:block}.results-head .muted{margin-top:6px}.request-form .request-action{grid-column:auto}}
.document-kpis{grid-template-columns:repeat(5,minmax(0,1fr))}.document-kpis .tax-total{background:linear-gradient(135deg,#0b1f5b,#2454d6);border-color:transparent}.document-kpis .tax-total span,.document-kpis .tax-total strong{color:#fff}.product-table{min-width:1500px}.product-table tfoot th{background:#eef4ff;color:#0b1f5b}.product-kpis{grid-template-columns:repeat(5,minmax(0,1fr))}.btn.secondary{white-space:nowrap}@media(max-width:900px){.product-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.product-filters>div[style]{grid-column:span 1!important}}@media print{.top,.hero,.tabs,.filters,.product-kpis,.pagination,.results-head .btn,.msg,.note,.tax-grid{display:none!important}.page{max-width:none;padding:0}.card{box-shadow:none;border:0;padding:0}.product-table{min-width:0}.product-table th,.product-table td{font-size:8px;padding:4px}.table-wrap{overflow:visible;border:0}}</style>
</head>
<body>
<header class="top"><div class="topin"><div class="brand"><img src="/assets/logo-nexa-prospero.jpg" alt="Próspero"><div><strong>Central do Contador Próspero</strong><span>Área contábil e fiscal</span></div></div><div class="user"><span><?= accountant_e(accountant_name()) ?></span><a href="?<?= $selected>0?'company='.$selected.'&':'' ?>view=settings">Minha conta</a><a href="logout.php">Sair</a></div></div></header>
<main class="page">
  <div class="hero"><div><h1><?php if($view==='requests'): ?>Solicitações de acesso<?php elseif($view==='settings'): ?>Minha conta<?php elseif($view==='products' && $company): ?>Produtos fiscais — <?= accountant_e((string)$company['name']) ?><?php elseif($company): ?><?= accountant_e((string)$company['name']) ?><?php else: ?>Central do Contador<?php endif; ?></h1><p><?php if($view==='requests'): ?>Solicite acesso usando o CNPJ das empresas que você contabiliza e acompanhe a aprovação.<?php elseif($view==='settings'): ?>Atualize sua senha de acesso à Central.<?php elseif($view==='products'): ?>Pesquise produtos por período, NCM, CEST, CFOP e códigos tributários para conferência contábil.<?php else: ?>Consulte fechamentos publicados, documentos fiscais e totais tributários.<?php endif; ?></p></div><?php if($companies): ?><form class="company-select" method="get"><input type="hidden" name="view" value="<?= accountant_e(in_array($view,['closures','documents','products'],true)?$view:'closures') ?>"><select name="company" onchange="this.form.submit()"><?php foreach($companies as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$c['id']===$selected?'selected':'' ?>><?= accountant_e((string)$c['name']) ?></option><?php endforeach; ?></select></form><?php endif; ?></div>
  <?php if($err!==''): ?><div class="msg err"><?= accountant_e($err) ?></div><?php endif; ?>
  <?php if($ok!==''): ?><div class="msg ok"><?= accountant_e($ok) ?></div><?php endif; ?>
  <nav class="tabs"><?php if($companies): ?><a class="<?= $view==='closures'?'active':'' ?>" href="?company=<?= $selected ?>&view=closures">Fechamentos contábeis</a><a class="<?= $view==='documents'?'active':'' ?>" href="?company=<?= $selected ?>&view=documents">Documentos fiscais</a><a class="<?= $view==='products'?'active':'' ?>" href="?company=<?= $selected ?>&view=products">Produtos</a><?php endif; ?><a class="<?= $view==='requests'?'active':'' ?>" href="?view=requests">Empresas e acessos<?php if($pendingRequests>0): ?><span class="count"><?= $pendingRequests ?></span><?php endif; ?></a><a class="<?= $view==='settings'?'active':'' ?>" href="?view=settings">Minha conta</a></nav>

<?php if($view==='requests'): ?>
  <section class="card"><h2>Solicitar acesso a uma empresa</h2><p class="muted">Informe exatamente o CNPJ cadastrado nas configurações fiscais da empresa. A solicitação ficará pendente até o administrador autorizar.</p><form method="post" class="request-form"><input type="hidden" name="csrf" value="<?= accountant_e(accountant_csrf()) ?>"><input type="hidden" name="action" value="request_access"><div><label>CNPJ da empresa</label><input name="company_cnpj" inputmode="numeric" maxlength="18" placeholder="00.000.000/0000-00" required></div><div><label>Mensagem opcional</label><textarea name="request_message" maxlength="500" placeholder="Ex.: Sou responsável pela contabilidade desta empresa."></textarea></div><div class="request-action"><button class="btn" type="submit">Enviar solicitação</button></div></form></section>
  <section class="card"><div class="results-head"><h2>Minhas empresas e solicitações</h2><div class="muted"><?= count($companies) ?> acesso(s) ativo(s) · <?= $pendingRequests ?> pendente(s)</div></div><div class="table-wrap"><table class="table requests"><thead><tr><th>Empresa</th><th>CNPJ solicitado</th><th>Solicitado em</th><th>Situação</th><th>Observação</th></tr></thead><tbody><?php if(!$requests): ?><tr><td colspan="5" class="empty">Você ainda não solicitou acesso a nenhuma empresa.</td></tr><?php endif; ?><?php foreach($requests as $request): $requestStatus=strtoupper((string)($request['status'] ?? 'PENDENTE')); ?><tr><td><strong><?= accountant_e((string)($request['company_display_name'] ?: $request['company_name'])) ?></strong></td><td><?= accountant_e((string)$request['requested_cnpj']) ?></td><td><?= !empty($request['requested_at'])?date('d/m/Y H:i',strtotime((string)$request['requested_at'])):'—' ?></td><td><span class="request-status <?= accountant_e($statusClass($requestStatus)) ?>"><?= accountant_e($requestStatus) ?></span></td><td><?= accountant_e((string)($request['review_note'] ?: $request['request_message'] ?: '—')) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="note">Quando a solicitação for aprovada, a empresa aparecerá automaticamente no seletor superior e os fechamentos/documentos liberados ficarão disponíveis.</div></section>

<?php elseif($view==='documents'): ?>
